# Hashed environments list in GNU R's chain order; env.profile shows the
# table, HASHPRI's counting and the resize (docs/g3.md §5.2).
e <- new.env()
for (n in c("b", "a", "zz", "x1", "x2", "foo", "bar")) assign(n, 1, envir = e)
print(ls(e, sorted = FALSE))
p <- env.profile(e)
print(p$size); print(p$nchains); print(which(p$counts > 0) - 1L)
rm("a", envir = e); assign("a", 2, envir = e)
print(ls(e, sorted = FALSE))
e <- new.env()
for (i in 1:26) assign(paste0("v", i), i, envir = e)
p <- env.profile(e)
print(p$size); print(p$nchains)
print(ls(e, sorted = FALSE))
e <- new.env(size = 5L)
for (n in letters[1:8]) assign(n, 1, envir = e)
print(env.profile(e)$size)
print(ls(e, sorted = FALSE))
print(names(as.list(e)))
